package org.eclipse.rdf4j.sail.memory.benchmark;

import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.TearDown;
import org.openjdk.jmh.annotations.Warmup;

/**
 * Measures the per-row cost of pulling a public Sail result, which includes the connection's operation admission and
 * cancellation bookkeeping on every {@code hasNext()} and {@code next()}.
 */
@State(Scope.Benchmark)
@Warmup(iterations = 5)
@BenchmarkMode({ Mode.AverageTime })
@Fork(value = 1, jvmArgs = { "-Xms2G", "-Xmx2G" })
@Measurement(iterations = 10)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
public class SailResultPullBenchmark {

	private static final int STATEMENTS = 1_000_000;

	private MemoryStore store;

	@Setup(Level.Trial)
	public void setup() {
		store = new MemoryStore();
		store.init();
		ValueFactory values = store.getValueFactory();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (int i = 0; i < STATEMENTS; i++) {
				connection.addStatement(values.createIRI("urn:pull:s" + (i % 1000)), RDF.VALUE,
						values.createLiteral(i));
			}
			connection.commit();
		}
	}

	@TearDown(Level.Trial)
	public void tearDown() {
		store.shutDown();
	}

	@Benchmark
	public long pullAllStatements() {
		long count = 0;
		try (SailConnection connection = store.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
						false)) {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		}
		return count;
	}
}
